-- Down 只恢复旧表的最小结构，不反向还原统一模型数据。
CREATE TABLE IF NOT EXISTS data_opcua_configs (connection_id uuid PRIMARY KEY REFERENCES data_connections(id) ON DELETE CASCADE, endpoint text NOT NULL, security_policy text NOT NULL DEFAULT 'None', security_mode text NOT NULL DEFAULT 'None', auth_type text NOT NULL DEFAULT 'anonymous', username text, password text, sampling_ms integer NOT NULL DEFAULT 1000, options jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS data_modbus_configs (connection_id uuid PRIMARY KEY REFERENCES data_connections(id) ON DELETE CASCADE, mode text NOT NULL DEFAULT 'tcp', host text, port integer, serial_config jsonb, slave_id integer NOT NULL DEFAULT 1, start_address integer NOT NULL DEFAULT 0, quantity integer NOT NULL DEFAULT 1, poll_interval_ms integer NOT NULL DEFAULT 1000, options jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS data_s7_configs (connection_id uuid PRIMARY KEY REFERENCES data_connections(id) ON DELETE CASCADE, host text NOT NULL, port integer NOT NULL DEFAULT 102, rack integer NOT NULL DEFAULT 0, slot integer NOT NULL DEFAULT 1, poll_interval_ms integer NOT NULL DEFAULT 1000, options jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS data_opcua_node_groups (id uuid PRIMARY KEY, project_id uuid NOT NULL, connection_id uuid NOT NULL REFERENCES data_connections(id) ON DELETE CASCADE, parent_id uuid, name text NOT NULL, description text, sort_order integer NOT NULL DEFAULT 0, created_by uuid NOT NULL, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS data_opcua_nodes (id uuid PRIMARY KEY, project_id uuid NOT NULL, connection_id uuid NOT NULL REFERENCES data_connections(id) ON DELETE CASCADE, group_id uuid, name text NOT NULL, code text NOT NULL, node_id text NOT NULL, browse_name text, display_name text, data_type text NOT NULL, unit text, sampling_ms integer NOT NULL DEFAULT 1000, deadband numeric(20,6), access_level text NOT NULL DEFAULT 'Read', description text, sort_order integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'active', created_by uuid NOT NULL, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS data_modbus_register_groups (id uuid PRIMARY KEY, project_id uuid NOT NULL, connection_id uuid NOT NULL REFERENCES data_connections(id) ON DELETE CASCADE, parent_id uuid, name text NOT NULL, description text, sort_order integer NOT NULL DEFAULT 0, created_by uuid NOT NULL, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS data_modbus_slave_devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, connection_id uuid NOT NULL REFERENCES data_connections(id) ON DELETE CASCADE, unit_id integer NOT NULL, name text NOT NULL, enabled boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0, created_by uuid NOT NULL, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS data_modbus_registers (id uuid PRIMARY KEY, project_id uuid NOT NULL, connection_id uuid NOT NULL REFERENCES data_connections(id) ON DELETE CASCADE, group_id uuid, name text NOT NULL, code text NOT NULL, unit_id integer NOT NULL, area text NOT NULL, address integer NOT NULL, address_base text NOT NULL DEFAULT 'modicon', protocol_address integer NOT NULL, quantity integer NOT NULL DEFAULT 1, data_type text NOT NULL, byte_order text NOT NULL DEFAULT 'ABCD', word_order text NOT NULL DEFAULT 'high_first', bit_index integer, scale numeric(20,6) NOT NULL DEFAULT 1, offset_value numeric(20,6) NOT NULL DEFAULT 0, unit text, poll_interval_ms integer NOT NULL DEFAULT 1000, timeout_ms integer, retry_count integer, access_level text NOT NULL DEFAULT 'Read', description text, sort_order integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'active', created_by uuid NOT NULL, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS data_s7_plc_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, connection_id uuid NOT NULL REFERENCES data_connections(id) ON DELETE CASCADE, host text NOT NULL, port integer NOT NULL DEFAULT 102, rack integer NOT NULL DEFAULT 0, slot integer NOT NULL DEFAULT 1, local_tsap text, remote_tsap text, connect_timeout_ms integer NOT NULL DEFAULT 3000, created_by uuid NOT NULL, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS data_s7_variable_groups (id uuid PRIMARY KEY, project_id uuid NOT NULL, connection_id uuid NOT NULL REFERENCES data_connections(id) ON DELETE CASCADE, parent_id uuid, name text NOT NULL, code text NOT NULL, description text, sort_order integer NOT NULL DEFAULT 0, created_by uuid NOT NULL, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS data_s7_variables (id uuid PRIMARY KEY, project_id uuid NOT NULL, connection_id uuid NOT NULL REFERENCES data_connections(id) ON DELETE CASCADE, group_id uuid, name text NOT NULL, code text NOT NULL, description text, area text NOT NULL, db_number integer, byte_offset integer NOT NULL, bit_offset integer, address_text text NOT NULL, normalized_address text NOT NULL, address_type text NOT NULL, read_length integer NOT NULL DEFAULT 1, data_type text NOT NULL, length integer, array_length integer, byte_order text NOT NULL DEFAULT 'big_endian', word_order text NOT NULL DEFAULT 'big_endian', scale numeric(20,6) NOT NULL DEFAULT 1, offset_value numeric(20,6) NOT NULL DEFAULT 0, unit text, poll_interval_ms integer NOT NULL DEFAULT 1000, quality_rule jsonb NOT NULL DEFAULT '{}'::jsonb, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, sort_order integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'active', created_by uuid NOT NULL, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
